# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not item.email:
            name = item.display_name
            raise ProjectError(f"no email for {name}")


def _name_key(student: Student) -> str:
    return student.display_name.lower()


def _pad_rows(rows: List[tuple]) -> List[str]:
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [
        "  ".join(
            cell.ljust(wide)
            for cell, wide in zip(row, widths)
        ).rstrip()
        for row in rows
    ]


# ---
def contact_sheet(students: List[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _check(students)
    ordered = sorted(students, key=_name_key)
    return _pad_rows([
        (item.display_name, item.section, item.email)
        for item in ordered
    ])
